return [{ json: {
  transcricao: "Teresa Nogueira enviou os documentos ao banco. Ficou de ir ao banco na proxima semana reunir com eles.",
  vendedor_nome: "Cesar"
} }];

// MONTAR PAYLOAD (TESTE GEMINI) — mesma logica/formato da producao, dados reais do Airtable.
const base = $('Entrada teste').first().json;
const trans = base.transcricao || '';
const VENDEDOR = base.vendedor_nome || 'Desconhecido';

const SEQ_UNIVERSAL = ['lead','aguarda_documentos','aguarda_decisao_banco','aprovado',
                       'proposta_enviada','aguarda_banco','escritura_marcada','fecho'];

let cfgRows = [];
try { cfgRows = ($('Get CONFIG').first().json.records) || []; } catch (e) {}
const cfg = {};
for (const r of cfgRows) {
  const f = r.fields || {};
  const k = f.chave || f.Chave || f.key || f.Nome || f.nome;
  const v = f.valor !== undefined ? f.valor : (f.Valor !== undefined ? f.Valor : f.value);
  if (!k) continue;
  let parsed = v;
  if (typeof v === 'string') { try { parsed = JSON.parse(v); } catch (e) { parsed = v; } }
  cfg[String(k).trim().toLowerCase()] = parsed;
}
const seqCfg = cfg['sequencia_estagios'] || cfg['sequencia'] || null;
const SEQUENCIA_ESTAGIOS = { ordem: (seqCfg && seqCfg.ordem) || (Array.isArray(seqCfg) ? seqCfg : SEQ_UNIVERSAL) };
const ETAPAS_OBRIGATORIAS = cfg['etapas_obrigatorias'] || [];
const FLAGS_AUTO = cfg['flags_auto'] || [];

let leadRecs = [];
try { leadRecs = ($('Get CANDIDATOS').first().json.records) || []; } catch (e) {}
const hoje = new Date();
const diasDesde = iso => {
  if (!iso) return null;
  const d = new Date(iso); if (isNaN(d)) return null;
  return Math.floor((hoje - d) / 86400000);
};
const CANDIDATOS = leadRecs.map(r => {
  const f = r.fields || {};
  const fase = f.estagio || f.Estagio || f['Estágio'] || 'lead';
  const idx = SEQUENCIA_ESTAGIOS.ordem.indexOf(fase);
  const cand = {
    id: r.id,
    nome: f.Nome || f.nome || '',
    telefone: f.Telefone || f.telefone || null,
    fase_atual: fase,
    tipo: f.tipo || 'aquisicao',
    ultima_nota: f.ultima_nota || null,
  };
  if (idx >= 0) cand.indice_fase = idx;
  const dd = diasDesde(f.ultimo_contacto || f.Data_ultimo_contacto || null);
  if (dd !== null) cand.dias_desde_ultimo_contacto = dd;
  return cand;
});

const DIAS = ['domingo','segunda-feira','terca-feira','quarta-feira','quinta-feira','sexta-feira','sabado'];
const MESES = ['janeiro','fevereiro','marco','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const iso = d => d.toISOString().slice(0, 10);

const CALENDARIO = [];
for (let i = 0; i <= 30; i++) {
  const d = new Date(hoje.getTime() + i * 86400000);
  CALENDARIO.push({ data: iso(d), dia_semana: DIAS[d.getDay()], offset_dias: i });
}
const CALENDARIO_MESES = [];
for (let m = 0; m < 12; m++) {
  const d = new Date(hoje.getFullYear(), hoje.getMonth() + m, 1);
  CALENDARIO_MESES.push({ mes: MESES[d.getMonth()], ano: d.getFullYear(), dia_1: iso(d), offset_meses: m });
}
const DATA_HOJE = iso(hoje) + ' (' + DIAS[hoje.getDay()] + ')';

const dinamico = {
  DATA_HOJE, VENDEDOR, TRANSCRICAO: trans, CANDIDATOS, CALENDARIO, CALENDARIO_MESES,
  SEQUENCIA_ESTAGIOS, ETAPAS_OBRIGATORIAS, FLAGS_AUTO,
};

const mensagem_utilizador = Object.entries(dinamico)
  .map(([k, v]) => k + ': ' + (typeof v === 'string' ? v : JSON.stringify(v)))
  .join('\n\n');

return [{ json: { vendedor: VENDEDOR, n_candidatos: CANDIDATOS.length, dinamico, mensagem_utilizador } }];

const sys = $json.data;
const msg = $('Montar Payload (teste)').first().json.mensagem_utilizador;
return [{ json: {
  system_instruction: { parts: [{ text: sys }] },
  contents: [{ role: 'user', parts: [{ text: msg }] }]
} }];

const raw = $json;
let texto = null;
try { texto = raw.candidates[0].content.parts[0].text; } catch (e) {}
let parsed = null;
if (texto) { try { parsed = JSON.parse(texto); } catch (e) {} }
const pacote = {
  transcricao_teste: $('Entrada teste').first().json.transcricao,
  resposta_texto: texto,
  resposta_json: parsed,
};
return [{ json: { pacote_string: JSON.stringify(pacote) } }];
